{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C13"],
      "claim": "Ginsenoside Rg3, the closest analogue sharing the same dammarane aglycone and C-3 disaccharide but lacking the C-20 disaccharide, showed low oral bioavailability in a human pharmacokinetic study; the additional sugar chain in the query would not improve absorption.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C30"],
      "claim": "Glycyrrhizin, a triterpenoid saponin with two sugar residues, has an absolute oral bioavailability of approximately 0.25% in humans, supporting very low oral absorption for large saponin glycosides.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C32"],
      "claim": "Acarbose, a polar pseudo-tetrasaccharide, has negligible absolute oral bioavailability of <2% in humans, consistent with poor systemic absorption of large hydrophilic glycosides.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Hydroxypropyl β-cyclodextrin, a large hydrophilic carbohydrate, has an oral bioavailability of less than 1% in humans, supporting low absorption for highly polar sugar-based molecules.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C27"],
      "claim": "Astragaloside IV, a triterpenoid saponin glycoside, has poor oral bioavailability in humans due to very low solubility in biological fluids, a relevant liability shared by the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Levovirin, a polar nucleoside, has an oral bioavailability of about 10% in humans, below the 20% threshold and consistent with poor permeability of highly polar glycosides.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All transferable experimental evidence from closely related saponins and large hydrophilic glycosides indicates very low oral bioavailability in humans, far below the 20% threshold. The query, ginsenoside Rb1, is larger and more polar than most of these analogues, so high oral bioavailability is not supported.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for ginsenoside Rb1 itself in humans.",
    "Most analogue records are qualitative or relative rather than exact F values, though all are far below 20%.",
    "Potential systemic exposure from gut-microbiota deglycosylation to metabolites is not captured by parent-compound bioavailability measurements."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

